def fill_summary(fills):
    qty = {}
    prices = {}
    for oid, q, p in fills:
        qty[oid] = qty.get(oid, 0) + q
        prices.setdefault(oid, []).append(p)
    return {oid: (qty[oid], sum(prices[oid]) / len(prices[oid])) for oid in qty}

