    return out

def fill_summary(fills):
    qty = {}
    spent = {}
    count = {}
    for oid, q, p in fills:
        qty[oid] = qty.get(oid, 0) + q
        spent[oid] = spent.get(oid, 0.0) + q * p
        count[oid] = count.get(oid, 0) + 1
    return {oid: (qty[oid], spent[oid] / count[oid]) for oid in qty}
